/**
 * Tests for Sentry no-op guard behavior (spec-13).
 * Verifies Sentry.init is NOT called when DSN env vars are absent.
 */

const mockInit = jest.fn();

jest.mock("@sentry/nextjs", () => ({
  init: mockInit,
}));

beforeEach(() => {
  jest.resetModules();
  mockInit.mockClear();
  delete process.env.SENTRY_DSN;
  delete process.env.NEXT_PUBLIC_SENTRY_DSN;
});

describe("sentry.client.config", () => {
  it("does not call Sentry.init when NEXT_PUBLIC_SENTRY_DSN is absent", async () => {
    await import("../../sentry.client.config");
    expect(mockInit).not.toHaveBeenCalled();
  });

  it("calls Sentry.init when NEXT_PUBLIC_SENTRY_DSN is set", async () => {
    process.env.NEXT_PUBLIC_SENTRY_DSN = "https://test@sentry.io/123";
    await import("../../sentry.client.config");
    expect(mockInit).toHaveBeenCalledWith(
      expect.objectContaining({ dsn: "https://test@sentry.io/123" })
    );
  });
});

describe("sentry.server.config", () => {
  it("does not call Sentry.init when SENTRY_DSN is absent", async () => {
    await import("../../sentry.server.config");
    expect(mockInit).not.toHaveBeenCalled();
  });

  it("calls Sentry.init when SENTRY_DSN is set", async () => {
    process.env.SENTRY_DSN = "https://test@sentry.io/456";
    await import("../../sentry.server.config");
    expect(mockInit).toHaveBeenCalledWith(
      expect.objectContaining({ dsn: "https://test@sentry.io/456" })
    );
  });
});

describe("sentry.edge.config", () => {
  it("does not call Sentry.init when SENTRY_DSN is absent", async () => {
    await import("../../sentry.edge.config");
    expect(mockInit).not.toHaveBeenCalled();
  });

  it("calls Sentry.init when SENTRY_DSN is set", async () => {
    process.env.SENTRY_DSN = "https://test@sentry.io/789";
    await import("../../sentry.edge.config");
    expect(mockInit).toHaveBeenCalledWith(
      expect.objectContaining({ dsn: "https://test@sentry.io/789" })
    );
  });
});

describe("instrumentation", () => {
  it("imports sentry.server.config when NEXT_RUNTIME is nodejs", async () => {
    process.env.NEXT_RUNTIME = "nodejs";
    const { register } = await import("../../instrumentation");
    await register();
    // No error thrown — register() executes without crashing
    expect(true).toBe(true);
  });

  it("imports sentry.edge.config when NEXT_RUNTIME is edge", async () => {
    process.env.NEXT_RUNTIME = "edge";
    const { register } = await import("../../instrumentation");
    await register();
    expect(true).toBe(true);
  });

  it("does nothing when NEXT_RUNTIME is not set", async () => {
    delete process.env.NEXT_RUNTIME;
    const { register } = await import("../../instrumentation");
    await register();
    expect(true).toBe(true);
  });
});

